// Unit Tests: Trade Notifications Service
// MODULE-14: NOTIF-V2-007

import {
  sendTradeNotificationPush,
  getTradeNotifications,
  markTradeNotificationRead,
  markAllTradeNotificationsRead,
  getUnreadTradeNotificationCount,
  TradeNotificationType,
} from '@/services/tradeNotifications';

// ─── Mock factory ─────────────────────────────────────────────────────────────
// Each test gets a fresh supabase mock via the factory pattern.

const mockFunctionsInvoke = jest.fn();

function buildSelectChain(resolvedValue: object) {
  const limitMock   = jest.fn().mockResolvedValue(resolvedValue);
  const orderMock   = jest.fn().mockReturnValue({ limit: limitMock });
  const isMock      = jest.fn().mockReturnValue({ order: orderMock });
  const eqMock: any = jest.fn();
  eqMock.mockReturnValue({ eq: eqMock, is: isMock, order: orderMock, maybeSingle: jest.fn().mockResolvedValue({ data: null, error: null }) });
  const selectMock  = jest.fn().mockReturnValue({ eq: eqMock });
  return { selectMock, eqMock, isMock, orderMock, limitMock };
}

function buildMaybeSingleChain(prefs: object | null) {
  const maybeSingleMock = jest.fn().mockResolvedValue({ data: prefs, error: null });
  const eqMock: any     = jest.fn();
  eqMock.mockReturnValue({ eq: eqMock, maybeSingle: maybeSingleMock });
  const selectMock      = jest.fn().mockReturnValue({ eq: eqMock });
  return { selectMock, maybeSingleMock };
}

function buildUpdateChain(resolvedValue: object) {
  const isMock    = jest.fn().mockResolvedValue(resolvedValue);
  const eqMock: any = jest.fn();
  eqMock.mockReturnValue({ eq: eqMock, is: isMock });
  const updateMock  = jest.fn().mockReturnValue({ eq: eqMock });
  return { updateMock, eqMock, isMock };
}

function buildCountChain(count: number | null, error: object | null) {
  const isMock    = jest.fn().mockResolvedValue({ count, error });
  const eqMock: any = jest.fn();
  eqMock.mockReturnValue({ eq: eqMock, is: isMock });
  const selectMock  = jest.fn().mockReturnValue({ eq: eqMock });
  return { selectMock, eqMock };
}

const mockFrom = jest.fn();

jest.mock('@/config/supabase', () => ({
  supabase: {
    from: (...args: any[]) => mockFrom(...args),
    functions: { invoke: (...args: any[]) => mockFunctionsInvoke(...args) },
  },
}));

// ─── Test data ─────────────────────────────────────────────────────────────────

const SELLER_ID = 'seller-uuid-001';
const BUYER_ID  = 'buyer-uuid-001';
const TRADE_ID  = 'trade-uuid-001';
const ITEM_ID   = 'item-uuid-001';

const baseData = {
  trade_id:   TRADE_ID,
  item_id:    ITEM_ID,
  item_title: 'Vintage Skateboard',
  deep_link:  `/trades/${TRADE_ID}`,
  type:       'trade_request' as TradeNotificationType,
};

const mockNotification = {
  id:         'notif-uuid-001',
  user_id:    SELLER_ID,
  category:   'trades' as const,
  type:       'trade_request' as TradeNotificationType,
  title:      'New Trade Request! 💬',
  body:       'Buyer wants your item',
  data:       baseData,
  is_read:    false,
  channels:   ['push', 'in_app'],
  created_at: '2026-04-15T10:00:00Z',
  read_at:    null,
};

// ─── sendTradeNotificationPush ─────────────────────────────────────────────────

describe('sendTradeNotificationPush()', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockFunctionsInvoke.mockResolvedValue({ data: { success: true }, error: null });
  });

  it('sends push when no preference row exists (defaults enabled)', async () => {
    const { selectMock } = buildMaybeSingleChain(null); // no pref row
    mockFrom.mockReturnValue({ select: selectMock });

    const result = await sendTradeNotificationPush(
      SELLER_ID, 'trade_request', 'Buyer wants to trade', baseData
    );

    expect(result.success).toBe(true);
    expect(mockFunctionsInvoke).toHaveBeenCalledWith('send-push-notification', {
      body: expect.objectContaining({
        userId:   SELLER_ID,
        title:    'New Trade Request! 💬',
        priority: 'high',
        data:     expect.objectContaining({ type: 'trade_request', category: 'trades' }),
      }),
    });
  });

  it('skips push when user preference push_enabled = false', async () => {
    const { selectMock } = buildMaybeSingleChain({ push_enabled: false });
    mockFrom.mockReturnValue({ select: selectMock });

    const result = await sendTradeNotificationPush(
      SELLER_ID, 'trade_request', 'Test body', baseData
    );

    expect(result.success).toBe(true);
    expect(mockFunctionsInvoke).not.toHaveBeenCalled();
  });

  it('sends push when user preference push_enabled = true', async () => {
    const { selectMock } = buildMaybeSingleChain({ push_enabled: true });
    mockFrom.mockReturnValue({ select: selectMock });

    const result = await sendTradeNotificationPush(
      SELLER_ID, 'trade_accepted', 'Seller accepted', { ...baseData, type: 'trade_accepted' }
    );

    expect(result.success).toBe(true);
    expect(mockFunctionsInvoke).toHaveBeenCalledWith('send-push-notification', {
      body: expect.objectContaining({ title: 'Trade Accepted! ✅' }),
    });
  });

  it('returns success=false when Edge Function errors', async () => {
    const { selectMock } = buildMaybeSingleChain(null);
    mockFrom.mockReturnValue({ select: selectMock });
    mockFunctionsInvoke.mockResolvedValue({ data: null, error: { message: 'Edge error' } });

    const result = await sendTradeNotificationPush(
      SELLER_ID, 'trade_completed', 'Trade done!', { ...baseData, type: 'trade_completed' }
    );

    expect(result.success).toBe(false);
    expect(result.error).toBe('Edge error');
  });

  it('returns error for empty userId without calling supabase', async () => {
    const result = await sendTradeNotificationPush('', 'trade_request', 'body', baseData);
    expect(result.success).toBe(false);
    expect(result.error).toMatch(/required/i);
    expect(mockFunctionsInvoke).not.toHaveBeenCalled();
    expect(mockFrom).not.toHaveBeenCalled();
  });

  it.each<[TradeNotificationType, string]>([
    ['trade_request',   'New Trade Request! 💬'],
    ['trade_accepted',  'Trade Accepted! ✅'],
    ['trade_rejected',  'Trade Declined'],
    ['trade_completed', 'Trade Complete! 🎉'],
    ['trade_cancelled', 'Trade Cancelled'],
  ])('uses correct title for %s', async (type, expectedTitle) => {
    jest.clearAllMocks();
    const { selectMock } = buildMaybeSingleChain(null);
    mockFrom.mockReturnValue({ select: selectMock });
    mockFunctionsInvoke.mockResolvedValue({ data: {}, error: null });

    await sendTradeNotificationPush(SELLER_ID, type, 'body', { ...baseData, type });

    expect(mockFunctionsInvoke).toHaveBeenCalledWith('send-push-notification', {
      body: expect.objectContaining({ title: expectedTitle }),
    });
  });
});

// ─── getTradeNotifications ────────────────────────────────────────────────────

describe('getTradeNotifications()', () => {
  beforeEach(() => jest.clearAllMocks());

  it('returns trade notifications for user', async () => {
    const { selectMock } = buildSelectChain({ data: [mockNotification], error: null });
    mockFrom.mockReturnValue({ select: selectMock });

    const result = await getTradeNotifications(SELLER_ID);

    expect(result.data).toHaveLength(1);
    expect(result.data[0].type).toBe('trade_request');
    expect(result.error).toBeUndefined();
  });

  it('queries user_notifications table', async () => {
    const { selectMock } = buildSelectChain({ data: [], error: null });
    mockFrom.mockReturnValue({ select: selectMock });

    await getTradeNotifications(SELLER_ID);

    expect(mockFrom).toHaveBeenCalledWith('user_notifications');
  });

  it('returns empty array when no notifications exist', async () => {
    const { selectMock } = buildSelectChain({ data: [], error: null });
    mockFrom.mockReturnValue({ select: selectMock });

    const result = await getTradeNotifications(BUYER_ID);
    expect(result.data).toEqual([]);
