    expect(acceptedNotif).toBeDefined();
    expect(acceptedNotif!.title).toContain('Accepted');
    expect(acceptedNotif!.data?.trade_id).toBe(tradeId);
  }, 15000);

  // ─── TC-E2E-003: trade_rejected ────────────────────────────────────────────

  it('TC-E2E-003: DB trigger creates trade_rejected notification for buyer when status → rejected', async () => {
    if (shouldSkipCase() || !admin) return;

    await clearTradeNotifications(admin, buyerId);

    const tradeId = await insertTestTrade(admin, buyerId, sellerId, itemId);
    createdTradeIds.push(tradeId);

    await updateTradeStatus(admin, tradeId, 'rejected');

    await new Promise((r) => setTimeout(r, 500));

    const notifs = await getTradeNotifs(admin, buyerId);
    const rejectedNotif = notifs.find((n) => n.type === 'trade_rejected');

    expect(rejectedNotif).toBeDefined();
    expect(rejectedNotif!.title).toContain('Declined');
  }, 15000);

  // ─── TC-E2E-004: trade_completed ───────────────────────────────────────────

  it('TC-E2E-004: DB trigger creates trade_completed notifications for BOTH buyer and seller', async () => {
    if (shouldSkipCase() || !admin) return;

    await clearTradeNotifications(admin, buyerId);
    await clearTradeNotifications(admin, sellerId);

    const tradeId = await insertTestTrade(admin, buyerId, sellerId, itemId);
    createdTradeIds.push(tradeId);

    await updateTradeStatus(admin, tradeId, 'accepted');
    await updateTradeStatus(admin, tradeId, 'completed');

    await new Promise((r) => setTimeout(r, 500));

    const buyerNotifs = await getTradeNotifs(admin, buyerId);
    const sellerNotifs = await getTradeNotifs(admin, sellerId);

    expect(buyerNotifs.find((n) => n.type === 'trade_completed')).toBeDefined();
    expect(sellerNotifs.find((n) => n.type === 'trade_completed')).toBeDefined();
  }, 15000);

  // ─── TC-E2E-005: trade_cancelled ───────────────────────────────────────────

  it('TC-E2E-005: DB trigger creates trade_cancelled notifications for BOTH parties', async () => {
    if (shouldSkipCase() || !admin) return;

    await clearTradeNotifications(admin, buyerId);
    await clearTradeNotifications(admin, sellerId);

    const tradeId = await insertTestTrade(admin, buyerId, sellerId, itemId);
    createdTradeIds.push(tradeId);

    await updateTradeStatus(admin, tradeId, 'cancelled');

    await new Promise((r) => setTimeout(r, 500));

    const buyerNotifs = await getTradeNotifs(admin, buyerId);
    const sellerNotifs = await getTradeNotifs(admin, sellerId);

    expect(buyerNotifs.find((n) => n.type === 'trade_cancelled')).toBeDefined();
    expect(sellerNotifs.find((n) => n.type === 'trade_cancelled')).toBeDefined();
  }, 15000);

  // ─── TC-E2E-006: notification_preferences gating ──────────────────────────

  it('TC-E2E-006: No notification created when seller has all trades channels disabled', async () => {
    if (shouldSkipCase() || !admin) return;

    await clearTradeNotifications(admin, sellerId);

    // Disable all trades channels for seller
    await admin.from('notification_preferences').upsert(
      {
        user_id: sellerId,
        category: 'trades',
        push_enabled: false,
        in_app_enabled: false,
        email_enabled: false,
      },
      { onConflict: 'user_id,category' }
    );

    const tradeId = await insertTestTrade(admin, buyerId, sellerId, itemId);
    createdTradeIds.push(tradeId);

    await new Promise((r) => setTimeout(r, 500));

    const notifs = await getTradeNotifs(admin, sellerId);
    // No trade_request notification should be created
    expect(
      notifs.find((n) => n.type === 'trade_request' && n.data?.trade_id === tradeId)
    ).toBeUndefined();

    // Restore default preferences
    await admin.from('notification_preferences').upsert(
      {
        user_id: sellerId,
        category: 'trades',
        push_enabled: true,
        in_app_enabled: true,
        email_enabled: false,
      },
      { onConflict: 'user_id,category' }
    );
  }, 15000);

  // ─── TC-E2E-007: notification data includes item details ──────────────────

  it('TC-E2E-007: Trade notification data includes item_id, trade_id and deep_link', async () => {
    if (shouldSkipCase() || !admin) return;

    await clearTradeNotifications(admin, sellerId);

    const tradeId = await insertTestTrade(admin, buyerId, sellerId, itemId);
    createdTradeIds.push(tradeId);

    await new Promise((r) => setTimeout(r, 500));

    const notifs = await getTradeNotifs(admin, sellerId);
    const notif = notifs.find((n) => n.type === 'trade_request' && n.data?.trade_id === tradeId);

    expect(notif).toBeDefined();
    expect(notif!.data.item_id).toBe(itemId);
    expect(notif!.data.deep_link).toBe(`/trades/${tradeId}`);
    expect(notif!.data.type).toBe('trade_request');
  }, 15000);
});

